.sl-slider-glass {
    position: relative;
    background-color: var(--smartlearn-bg);
    font-family: var(--smartlearn-body-font, inherit);
    overflow: hidden;
}
.sl-slider-glass .sl-container {
    width: 100%;
    max-width: 1200px;
    margin-inline: auto;
    padding-inline: 1rem;
}
.sl-slider-glass .carousel-inner { touch-action: pan-y; }
.sl-slider-glass .carousel-item { height: 80vh; min-height: 550px; max-height: 800px; }
.sl-slider-glass .sl-glass-bg { position: absolute; inset: 0; width: 100%; height: 100%; z-index: 1; }
.sl-slider-glass .sl-glass-bg::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(110deg, rgba(15, 23, 42, 0.65) 0%, rgba(15, 23, 42, 0.35) 100%);
}
.sl-slider-glass .sl-glass-bg img { width: 100%; height: 100%; object-fit: cover; }
.sl-slider-glass .sl-glass-container { position: relative; height: 100%; z-index: 2; display: flex; align-items: center; }
.sl-slider-glass .sl-glass-card {
    background: rgba(15, 23, 42, 0.55);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid rgba(255, 255, 255, 0.25);
    padding: 3rem;
    border-radius: var(--smartlearn-radius, 1rem);
    max-width: 500px;
    color: #fff;
    box-shadow: 0 20px 40px rgba(0,0,0,0.28);
    opacity: 0;
}
.sl-slider-glass .carousel-item.active .sl-glass-card {
    animation: sl-slider-glass-up 0.7s ease forwards;
}
.sl-slider-glass .sl-glass-tag {
    display: inline-block;
    padding: 0.25rem 0.75rem;
    background: rgba(0,0,0,0.4);
    color: #fff;
    border-radius: 1rem;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    margin-bottom: 1rem;
    letter-spacing: 0.05em;
}
.sl-slider-glass .sl-glass-title {
    font-family: var(--smartlearn-heading-font, inherit);
    font-size: clamp(1.85rem, 3vw, 2.5rem);
    font-weight: 700;
    color: #fff;
    margin-bottom: 1rem;
    line-height: 1.2;
}
.sl-slider-glass .sl-glass-desc {
    font-size: 1.125rem;
    color: rgba(255,255,255,0.92);
    margin-bottom: 2rem;
    line-height: 1.6;
}
.sl-slider-glass .sl-btn-glass {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
    border: 1px solid transparent;
    font-weight: 700;
    padding: 0.75rem 2rem;
    border-radius: 0.5rem;
    transition: background-color 0.2s ease, transform 0.2s ease;
}
.sl-slider-glass .sl-btn-glass:hover,
.sl-slider-glass .sl-btn-glass:focus-visible {
    background-color: var(--smartlearn-btn-hover-bg);
    color: var(--smartlearn-btn-text);
    transform: translateY(-2px);
}
.sl-slider-glass .sl-btn-glass:focus-visible,
.sl-slider-glass .sl-glass-arrows button:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 3px;
}
.sl-slider-glass .sl-glass-nav-container {
    position: absolute;
    bottom: 3rem;
    inset-inline: 0;
    z-index: 10;
    display: flex;
}
.sl-slider-glass .sl-glass-nav {
    display: flex;
    align-items: center;
    gap: 1.5rem;
    background: rgba(15, 23, 42, 0.72);
    backdrop-filter: blur(8px);
    padding: 0.65rem 1.25rem;
    border-radius: 2rem;
    border: 1px solid rgba(255,255,255,0.2);
    color: #fff;
}
.sl-slider-glass .sl-glass-counter { font-family: monospace; font-size: 1.125rem; letter-spacing: 2px; }
.sl-slider-glass .sl-glass-divider { opacity: 0.6; margin: 0 0.25rem; }
.sl-slider-glass .sl-glass-arrows { display: flex; gap: 0.5rem; align-items: center; }
.sl-slider-glass .sl-glass-arrows button {
    background: transparent;
    border: 1px solid rgba(255,255,255,0.4);
    color: #fff;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: background-color 0.2s ease, color 0.2s ease;
}
.sl-slider-glass .sl-glass-arrows button:hover {
    background: #fff;
    color: #0f172a !important;
}
[dir="rtl"] .sl-slider-glass .sl-glass-prev svg,
[dir="rtl"] .sl-slider-glass .sl-glass-next svg {
    transform: scaleX(-1);
}
@keyframes sl-slider-glass-up {
    from { opacity: 0; transform: translateY(30px); }
    to { opacity: 1; transform: translateY(0); }
}
@media (max-width: 767px) {
    .sl-slider-glass .sl-glass-card { padding: 2rem; }
    .sl-slider-glass .sl-glass-nav-container { justify-content: center; bottom: 1.5rem; }
}
@media (prefers-reduced-motion: reduce) {
    .sl-slider-glass .sl-glass-card,
    .sl-slider-glass .carousel-item.active .sl-glass-card {
        animation: none;
        opacity: 1;
        transform: none;
    }
    .sl-slider-glass .sl-btn-glass,
    .sl-slider-glass .sl-glass-arrows button { transition: none; }
}

